## II. ZIG GATEWAY ÉS CEREBRAS ORCHESTRATOR

### 2.1 Cerebras API Client Implementáció (Zig)

A Zig nyelv zero-allocation async modellje ideális a Cerebras 4000-5000 token/s streaming kezeléséhez.

**zig_gateway/build.zig:**
```zig
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const exe = b.addExecutable(.{
        .name = "neural_search_gateway",
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    // Link libcurl for HTTP requests
    exe.linkSystemLibrary("curl");
    exe.linkSystemLibrary("ssl");
    exe.linkSystemLibrary("crypto");
    exe.linkSystemLibrary("z");
    exe.linkSystemLibrary("zstd");

    // Link hiredis for Dragonfly
    exe.linkSystemLibrary("hiredis");

    exe.linkLibC();

    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());

    const run_step = b.step("run", "Run the gateway");
    run_step.dependOn(&run_cmd.step);

    // Tests
    const unit_tests = b.addTest(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const run_tests = b.addRunArtifact(unit_tests);
    const test_step = b.step("test", "Run unit tests");
    test_step.dependOn(&run_tests.step);
}
```

**zig_gateway/src/cerebras_client.zig:**
```zig
const std = @import("std");
const http = @import("http");
const json = std.json;

pub const ModelTier = enum {
    speed, // Qwen 235B - 4000-5000 t/s
    balanced, // GPT-OSS 120B - 2500-3500 t/s
    smart, // GLM 4.7 - 300-1000 t/s (SOTA reasoning)
};

pub const CerebrasConfig = struct {
    api_key: []const u8,
    base_url: []const u8 = "",
    timeout_ms: u64 = 120000,
    max_retries: u8 = 3,
};

pub const CompletionRequest = struct {
    model: []const u8,
    prompt: []const u8,
    max_tokens: u32,
    temperature: f32 = 0.7,
    top_p: f32 = 0.95,
    stream: bool = true,
    stop: ?[]const []const u8 = null,
};

pub const StreamChunk = struct {
    token: []const u8,
    is_final: bool,
    total_tokens: u32,
    finish_reason: ?[]const u8,
};

pub const CerebrasClient = struct {
    allocator: std.mem.Allocator,
    config: CerebrasConfig,
    curl_handle: *anyopaque,

    pub fn init(allocator: std.mem.Allocator, config: CerebrasConfig) !CerebrasClient {
        // Initialize libcurl globally
        const curl = @cImport({
            @cInclude("curl/curl.h");
        });

        const handle = curl.curl_easy_init() orelse return error.CurlInitFailed;

        return CerebrasClient{
            .allocator = allocator,
            .config = config,
            .curl_handle = handle,
        };
    }

    pub fn deinit(self: *CerebrasClient) void {
        const curl = @cImport(@cInclude("curl/curl.h"));
        curl.curl_easy_cleanup(self.curl_handle);
    }

    pub fn getModelId(tier: ModelTier) []const u8 {
        return switch (tier) {
            .speed => "qwen-235b-flash", // 4000-5000 t/s
            .balanced => "gpt-oss-120b",
            .smart => "glm-4.7-reasoner", // SOTA, beats GPT-5.2
        };
    }

    pub fn streamCompletion(
        self: *CerebrasClient,
        request: CompletionRequest,
        callback: *const fn(StreamChunk) anyerror!void,
    ) !void {
        const curl = @cImport(@cInclude("curl/curl.h"));

        // Build JSON payload
        var payload_buffer = std.ArrayList(u8).init(self.allocator);
        defer payload_buffer.deinit();

        try std.json.stringify(request, .{}, payload_buffer.writer());
        const payload = try payload_buffer.toOwnedSlice();
        defer self.allocator.free(payload);

        // Set URL
        const url = try std.fmt.allocPrint(
            self.allocator,
            "{s}/completions",
            .{self.config.base_url},
        );
        defer self.allocator.free(url);

        _ = curl.curl_easy_setopt(self.curl_handle, curl.CURLOPT_URL, url.ptr);
        _ = curl.curl_easy_setopt(self.curl_handle, curl.CURLOPT_POST, @as(c_long, 1));
        _ = curl.curl_easy_setopt(self.curl_handle, curl.CURLOPT_POSTFIELDS, payload.ptr);
        _ = curl.curl_easy_setopt(self.curl_handle, curl.CURLOPT_POSTFIELDSIZE, payload.len);

        // Set headers
        const auth_header = try std.fmt.allocPrint(
            self.allocator,
            "Authorization: Bearer {s}",
            .{self.config.api_key},
        );
        defer self.allocator.free(auth_header);

        var headers: ?*curl.curl_slist = null;
        headers = curl.curl_slist_append(headers, "Content-Type: application/json");
        headers = curl.curl_slist_append(headers, "Accept: text/event-stream");
        headers = curl.curl_slist_append(headers, auth_header.ptr);
        defer curl.curl_slist_free_all(headers);

        _ = curl.curl_easy_setopt(self.curl_handle, curl.CURLOPT_HTTPHEADER, headers);

        // Streaming callback context
        const CallbackContext = struct {
            allocator: std.mem.Allocator,
            user_callback: *const fn(StreamChunk) anyerror!void,
            buffer: std.ArrayList(u8),
        };

        var context = CallbackContext{
            .allocator = self.allocator,
            .user_callback = callback,
            .buffer = std.ArrayList(u8).init(self.allocator),
        };
        defer context.buffer.deinit();

        // Write callback for streaming
        const writeCallback = struct {
            fn call(
                ptr: [*c]u8,
                size: usize,
                nmemb: usize,
                userdata: ?*anyopaque,
            ) callconv(.C) usize {
                const ctx = @as(*CallbackContext, @ptrCast(@alignCast(userdata)));
                const total_size = size * nmemb;
                const data = ptr[0..total_size];

                // Parse SSE (Server-Sent Events) format
                // Format: "data: {json}\n\n"

                ctx.buffer.appendSlice(data) catch return 0;

                // Process complete SSE events
                while (std.mem.indexOf(u8, ctx.buffer.items, "\n\n")) |end_idx| {
                    const event_data = ctx.buffer.items[0..end_idx];
                    defer ctx.buffer.replaceRange(0, end_idx + 2, &[_]u8{}) catch {};

                    if (std.mem.startsWith(u8, event_data, "data: ")) {
                        const json_data = event_data[6..];

                        if (std.mem.eql(u8, json_data, "[DONE]")) {
                            // Stream finished
                            continue;
                        }

                        // Parse JSON chunk
                        const parsed = std.json.parseFromSlice(
                            struct {
                                choices: []struct {
                                    delta: struct {
                                        content: ?[]const u8 = null,
                                    },
                                    finish_reason: ?[]const u8 = null,
                                },
                                usage: ?struct {
                                    total_tokens: u32,
                                } = null,
                            },
                            ctx.allocator,
                            json_data,
                            .{},
                        ) catch continue;
                        defer parsed.deinit();

                        if (parsed.value.choices.len > 0) {
                            const choice = parsed.value.choices[0];

                            if (choice.delta.content) |content| {
                                const chunk = StreamChunk{
                                    .token = content,
                                    .is_final = choice.finish_reason != null,
                                    .total_tokens = if (parsed.value.usage) |u| u.total_tokens else 0,
                                    .finish_reason = choice.finish_reason,
                                };

                                ctx.user_callback(chunk) catch return 0;
                            }
                        }
                    }
                }

                return total_size;
            }
        }.call;

        _ = curl.curl_easy_setopt(
            self.curl_handle,
            curl.CURLOPT_WRITEFUNCTION,
            writeCallback,
        );
        _ = curl.curl_easy_setopt(
            self.curl_handle,
            curl.CURLOPT_WRITEDATA,
            @as(*anyopaque, @ptrCast(&context)),
        );

        // Timeout
        _ = curl.curl_easy_setopt(
            self.curl_handle,
            curl.CURLOPT_TIMEOUT_MS,
            @as(c_long, @intCast(self.config.timeout_ms)),
        );

        // Execute request
        const result = curl.curl_easy_perform(self.curl_handle);

        if (result != curl.CURLE_OK) {
            return error.CurlRequestFailed;
        }

        // Check HTTP response code
        var response_code: c_long = 0;
        _ = curl.curl_easy_getinfo(
            self.curl_handle,
            curl.CURLINFO_RESPONSE_CODE,
            &response_code,
        );

        if (response_code < 200 or response_code >= 300) {
            return error.HttpError;
        }
    }
};
```

**zig_gateway/src/router.zig:**
```zig
const std = @import("std");
const cerebras = @import("cerebras_client.zig");

pub const QueryComplexity = enum {
    simple, // Single-fact lookup: "Capital of France?"
    moderate, // Multi-fact synthesis: "Compare X and Y"
    complex, // Deep reasoning: "Analyze trends in quantum computing 2020-2026"
};

pub const RouterDecision = struct {
    model_tier: cerebras.ModelTier,
    search_depth: u8, // Number of documents to retrieve (10-100)
    use_reranking: bool,
    enable_deep_research: bool, // Activates Websets multi-agent
    reasoning_mode: bool, // GLM 4.7 special handling
};

pub const Router = struct {
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) Router {
        return Router{ .allocator = allocator };
    }

    pub fn analyzeQuery(self: *Router, query: []const u8) !RouterDecision {
        const complexity = self.classifyComplexity(query);

        return switch (complexity) {
            .simple => RouterDecision{
                .model_tier = .speed, // Qwen 235B @ 4-5k t/s
                .search_depth = 10,
                .use_reranking = false,
                .enable_deep_research = false,
                .reasoning_mode = false,
            },
            .moderate => RouterDecision{
                .model_tier = .balanced, // GPT-OSS 120B
                .search_depth = 30,
                .use_reranking = true,
                .enable_deep_research = false,
                .reasoning_mode = false,
            },
            .complex => RouterDecision{
                .model_tier = .smart, // GLM 4.7 SOTA
                .search_depth = 100,
                .use_reranking = true,
                .enable_deep_research = true,
                .reasoning_mode = true,
            },
        };
    }

    fn classifyComplexity(self: *Router, query: []const u8) QueryComplexity {
        _ = self;

        // Heuristics for complexity classification
        const word_count = countWords(query);
        const has_comparison = std.mem.indexOf(u8, query, "compare") != null or
                              std.mem.indexOf(u8, query, "difference") != null or
                              std.mem.indexOf(u8, query, "versus") != null;
        const has_analysis = std.mem.indexOf(u8, query, "analyze") != null or
                            std.mem.indexOf(u8, query, "explain why") != null or
                            std.mem.indexOf(u8, query, "reasoning") != null;
        const has_code = std.mem.indexOf(u8, query, "code") != null or
                        std.mem.indexOf(u8, query, "implement") != null or
                        std.mem.indexOf(u8, query, "algorithm") != null;
        const has_temporal = std.mem.indexOf(u8, query, "trend") != null or
                            std.mem.indexOf(u8, query, "over time") != null or
                            std.mem.indexOf(u8, query, "history") != null;

        if (word_count < 5 and !has_comparison and !has_analysis) {
            return .simple;
        }

        if (has_analysis or has_code or has_temporal or (has_comparison and word_count > 10)) {
            return .complex;
        }

        return .moderate;
    }

    fn countWords(text: []const u8) usize {
        var count: usize = 0;
        var in_word = false;

        for (text) |char| {
            if (std.ascii.isWhitespace(char)) {
                in_word = false;
            } else if (!in_word) {
                in_word = true;
                count += 1;
            }
        }

        return count;
    }
};
```

**zig_gateway/src/dragonfly_client.zig:**
```zig
const std = @import("std");

pub const DragonflyConfig = struct {
    endpoint: []const u8, // host:port
    password: ?[]const u8 = null,
    pool_size: u16 = 32,
    timeout_ms: u32 = 5000,
};

pub const DragonflyClient = struct {
    allocator: std.mem.Allocator,
    config: DragonflyConfig,
    connections: std.ArrayList(*Connection),
    mutex: std.Thread.Mutex,

    const Connection = struct {
        socket: std.net.Stream,
        in_use: bool,

        pub fn sendCommand(self: *Connection, args: []const []const u8) ![]const u8 {
            // Implement RESP3 protocol
            // Format: *<count>\r\n$<len1>\r\n<arg1>\r\n$<len2>\r\n<arg2>\r\n...

            var buffer = std.ArrayList(u8).init(self.allocator);
            defer buffer.deinit();

            try buffer.writer().print("*{d}\r\n", .{args.len});

            for (args) |arg| {
                try buffer.writer().print("${d}\r\n{s}\r\n", .{ arg.len, arg });
            }

            // Send
            try self.socket.writeAll(buffer.items);

            // Read response
            var response_buffer: [4096]u8 = undefined;
            const n = try self.socket.read(&response_buffer);

            return try std.mem.Allocator.dupe(u8, response_buffer[0..n]);
        }
    };

    pub fn init(allocator: std.mem.Allocator, config: DragonflyConfig) !DragonflyClient {
        var client = DragonflyClient{
            .allocator = allocator,
            .config = config,
            .connections = std.ArrayList(*Connection).init(allocator),
            .mutex = std.Thread.Mutex{},
        };

        // Initialize connection pool
        for (0..config.pool_size) |_| {
            const conn = try client.createConnection();
            try client.connections.append(conn);
        }

        return client;
    }

    fn createConnection(self: *DragonflyClient) !*Connection {
        // Parse endpoint
        const colon_idx = std.mem.indexOf(u8, self.config.endpoint, ":") orelse
            return error.InvalidEndpoint;
        const host = self.config.endpoint[0..colon_idx];
        const port = try std.fmt.parseInt(u16, self.config.endpoint[colon_idx + 1 ..], 10);

        // Connect
        const addr = try std.net.Address.parseIp(host, port);
        const socket = try std.net.tcpConnectToAddress(addr);

        const conn = try self.allocator.create(Connection);
        conn.* = Connection{
            .socket = socket,
            .in_use = false,
        };

        // Authenticate if password provided
        if (self.config.password) |pwd| {
            _ = try conn.sendCommand(&[_][]const u8{ "AUTH", pwd });
        }

        return conn;
    }

    pub fn getConnection(self: *DragonflyClient) !*Connection {
        self.mutex.lock();
        defer self.mutex.unlock();

        for (self.connections.items) |conn| {
            if (!conn.in_use) {
                conn.in_use = true;
                return conn;
            }
        }

        // All connections busy, create new one
        const conn = try self.createConnection();
        try self.connections.append(conn);
        conn.in_use = true;
        return conn;
    }

    pub fn releaseConnection(self: *DragonflyClient, conn: *Connection) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        conn.in_use = false;
    }

    pub fn get(self: *DragonflyClient, key: []const u8) !?[]const u8 {
        const conn = try self.getConnection();
        defer self.releaseConnection(conn);

        const response = try conn.sendCommand(&[_][]const u8{ "GET", key });

        // Parse RESP3 response
        if (response[0] == '$' and response[1] == '-') {
            // Null bulk string
            return null;
        }

        // Extract value (skip RESP3 headers)
        // Format: $<length>\r\n<data>\r\n
        const newline_idx = std.mem.indexOf(u8, response, "\r\n") orelse return error.InvalidResponse;
        return response[newline_idx + 2 .. response.len - 2];
    }

    pub fn set(self: *DragonflyClient, key: []const u8, value: []const u8) !void {
        const conn = try self.getConnection();
        defer self.releaseConnection(conn);

        _ = try conn.sendCommand(&[_][]const u8{ "SET", key, value });
    }

    pub fn pipeline(self: *DragonflyClient, commands: []const []const []const u8) !void {
        const conn = try self.getConnection();
        defer self.releaseConnection(conn);

        // Send all commands without waiting for responses
        for (commands) |cmd| {
            var buffer = std.ArrayList(u8).init(self.allocator);
            defer buffer.deinit();

            try buffer.writer().print("*{d}\r\n", .{cmd.len});
            for (cmd) |arg| {
                try buffer.writer().print("${d}\r\n{s}\r\n", .{ arg.len, arg });
            }

            try conn.socket.writeAll(buffer.items);
        }

        // Read all responses
        for (commands) |_| {
            var response_buffer: [1024]u8 = undefined;
            _ = try conn.socket.read(&response_buffer);
        }
    }

    pub fn deinit(self: *DragonflyClient) void {
        for (self.connections.items) |conn| {
            conn.socket.close();
            self.allocator.destroy(conn);
        }
        self.connections.deinit();
    }
};
