## IV. FUTHARK GPU VECTOR SEARCH ÉS EMBEDDING OPERATIONS

### 4.1 FAISS Wrapper és Vector Search (Futhark)

A Futhark nyelv tisztán funkcionális, párhuzamos array programozás GPU-kon, ideális a 8x B200 GPU kihasználására.

**futhark_embeddings/src/vector_search.fut:**
```futhark
-- FAISS-like vector search optimized for B200 GPUs
-- L2-normalized embeddings, inner product similarity

type embedding = []f32
type embeddings_matrix = [][]f32

-- Compute cosine similarity between query and all database embeddings
-- Optimized for B200: 180GB VRAM per GPU, 8 TB/s bandwidth
def cosine_similarity [n] [d] (query: [d]f32) (database: [n][d]f32): [n]f32 =
  map (\db_vec -> 
    let dot_product = f32.sum (map2 (*) query db_vec)
    -- Vectors are pre-normalized, so no need to divide by norms
    in dot_product
  ) database

-- Top-K selection using partial sorting
-- Returns indices and scores of top K elements
def top_k [n] (k: i64) (scores: [n]f32): ([k]i64, [k]f32) =
  let indices = iota n
  let pairs = zip indices scores
  -- Sort by score descending
  let sorted = 
    radix_sort_by_key (.1) (>!) pairs
  let top_pairs = take k sorted
  in unzip top_pairs

-- Batch vector search: multiple queries against database
-- Highly parallel across both queries and database vectors
def batch_search [nq] [nd] [d] (k: i64) 
                               (queries: [nq][d]f32) 
                               (database: [nd][d]f32): ([nq][k]i64, [nq][k]f32) =
  let results = 
    map (\query ->
      let similarities = cosine_similarity query database
      in top_k k similarities
    ) queries
  in unzip (map (\(idxs, scores) -> (idxs, scores)) results)

-- L2 normalization for embedding vectors
def normalize [d] (vec: [d]f32): [d]f32 =
  let norm = f32.sqrt (f32.sum (map (\x -> x * x) vec))
  let epsilon = 1e-8
  in map (\x -> x / (norm + epsilon)) vec

-- Batch normalize embeddings matrix
def batch_normalize [n] [d] (embeddings: [n][d]f32): [n][d]f32 =
  map normalize embeddings

-- IVF (Inverted File Index) structure for billion-scale search
-- Cluster centroids using k-means
type ivf_index [nc] [d] = {
  centroids: [nc][d]f32,
  cluster_assignments: []i64,
  cluster_sizes: [nc]i64
}

-- Assign vectors to nearest centroid
def assign_to_clusters [n] [nc] [d] (vectors: [n][d]f32) 
                                     (centroids: [nc][d]f32): [n]i64 =
  map (\vec ->
    let distances = map (\centroid ->
      let diff = map2 (-) vec centroid
      in f32.sum (map (\x -> x * x) diff)
    ) centroids
    let (min_idx, _) = reduce_comm (\(i1, d1) (i2, d2) ->
      if d1 < d2 then (i1, d1) else (i2, d2)
    ) (0, f32.inf) (zip (iota nc) distances)
    in min_idx
  ) vectors

-- IVF search: probe nprobe clusters
def ivf_search [n] [nc] [d] (k: i64) (nprobe: i64)
                             (query: [d]f32)
                             (index: ivf_index [nc] [d])
                             (database: [n][d]f32): ([k]i64, [k]f32) =
  -- Find nprobe nearest centroids
  let centroid_similarities = cosine_similarity query index.centroids
  let (probe_indices, _) = top_k nprobe centroid_similarities

  -- Search within selected clusters
  let cluster_results = 
    map (\cluster_idx ->
      let cluster_mask = 
        map (\assignment -> assignment == cluster_idx) index.cluster_assignments
      let cluster_vecs = 
        filter (\(_, mask) -> mask) (zip database cluster_mask)
        |> map (.0)
      let cluster_sims = cosine_similarity query cluster_vecs
      in zip (iota (length cluster_vecs)) cluster_sims
    ) probe_indices

  -- Merge results from all clusters
  let all_results = flatten cluster_results
  let (indices, scores) = unzip all_results

  -- Select top K globally
  let sorted = radix_sort_by_key (\(_, score) -> score) (>!) (zip indices scores)
  let top_pairs = take k sorted
  in unzip top_pairs

-- Product Quantization for memory efficiency
-- Compress 1024-dim vectors to 64 bytes (PQ64)
type pq_codebook [M] [K] [ds] = {
  codebooks: [M][K][ds]f32  -- M subquantizers, K centroids each, ds subvector dim
}

-- Encode vector using PQ
def pq_encode [d] [M] [K] [ds] (vec: [d]f32) 
                                (codebook: pq_codebook [M] [K] [ds]): [M]i64 =
  -- Split vector into M subvectors
  let subvectors = unflatten M ds vec

  -- Encode each subvector
  let codes = 
    map2 (\subvec cb_m ->
      -- Find nearest centroid
      let distances = map (\centroid ->
        let diff = map2 (-) subvec centroid
        in f32.sum (map (\x -> x * x) diff)
      ) cb_m
      let (min_idx, _) = reduce_comm (\(i1, d1) (i2, d2) ->
        if d1 < d2 then (i1, d1) else (i2, d2)
      ) (0, f32.inf) (zip (iota K) distances)
      in min_idx
    ) subvectors codebook.codebooks

  in codes

-- Asymmetric distance computation for PQ
-- Query is full precision, database vectors are quantized
def pq_asymmetric_distance [M] [K] [ds] (query: []f32)
                                         (codes: [M]i64)
                                         (codebook: pq_codebook [M] [K] [ds]): f32 =
  let query_subvectors = unflatten M ds query

  let distances = 
    map3 (\query_sub code cb_m ->
      let centroid = cb_m[code]
      let diff = map2 (-) query_sub centroid
      in f32.sum (map (\x -> x * x) diff)
    ) query_subvectors codes codebook.codebooks

  in f32.sum distances

-- Hybrid HNSW + IVF + PQ search (production configuration)
-- Entry point for billion-scale search on 8x B200
def hybrid_search [n] [nc] [d] [M] [K] [ds] 
                  (k: i64) (nprobe: i64)
                  (query: [d]f32)
                  (ivf_idx: ivf_index [nc] [d])
                  (pq_codes: [n][M]i64)
                  (pq_cb: pq_codebook [M] [K] [ds])
                  (database: [n][d]f32): ([k]i64, [k]f32) =
  -- IVF coarse search
  let centroid_sims = cosine_similarity query ivf_idx.centroids
  let (probe_indices, _) = top_k nprobe centroid_sims

  -- PQ refinement within clusters
  let cluster_results =
    map (\cluster_idx ->
      let cluster_mask = 
        map (\assignment -> assignment == cluster_idx) ivf_idx.cluster_assignments
      let cluster_indices = 
        filter (\(idx, mask) -> mask) (zip (iota n) cluster_mask)
        |> map (.0)
      let cluster_codes = map (\idx -> pq_codes[idx]) cluster_indices
      let cluster_distances = 
        map (\codes -> pq_asymmetric_distance query codes pq_cb) cluster_codes
      in zip cluster_indices cluster_distances
    ) probe_indices

  -- Global top-K selection
  let all_results = flatten cluster_results
  let sorted = radix_sort_by_key (.1) (<!) all_results
  let top_pairs = take k sorted
  let (top_indices, top_distances) = unzip top_pairs

  -- Convert distances to similarities (for cosine: sim = 1 - dist/2)
  let top_similarities = map (\d -> 1.0 - d / 2.0) top_distances

  in (top_indices, top_similarities)

-- Entry point for C FFI
entry search_vectors [nq] [nd] [d] (k: i64)
                                    (queries: [nq][d]f32)
                                    (database: [nd][d]f32): ([nq][k]i64, [nq][k]f32) =
  batch_search k queries database

entry normalize_embeddings [n] [d] (embeddings: [n][d]f32): [n][d]f32 =
  batch_normalize embeddings
