-- Advanced similarity and distance kernels for B200 GPU

-- Euclidean distance (L2)
def euclidean_distance [d] (a: [d]f32) (b: [d]f32): f32 =
  let diff = map2 (-) a b
  in f32.sqrt (f32.sum (map (\x -> x * x) diff))

-- Manhattan distance (L1)
def manhattan_distance [d] (a: [d]f32) (b: [d]f32): f32 =
  f32.sum (map2 (\x y -> f32.abs (x - y)) a b)

-- Hamming distance for binary embeddings
def hamming_distance [d] (a: [d]i32) (b: [d]i32): i32 =
  i32.sum (map2 (\x y -> if x == y then 0 else 1) a b)

-- Jaccard similarity for sets
def jaccard_similarity [d] (a: [d]f32) (b: [d]f32): f32 =
  let intersection = f32.sum (map2 f32.min a b)
  let union = f32.sum (map2 f32.max a b)
  in intersection / (union + 1e-8)

-- Pearson correlation coefficient
def pearson_correlation [d] (a: [d]f32) (b: [d]f32): f32 =
  let mean_a = f32.sum a / f32.i64 d
  let mean_b = f32.sum b / f32.i64 d
  let centered_a = map (\x -> x - mean_a) a
  let centered_b = map (\x -> x - mean_b) b
  let numerator = f32.sum (map2 (*) centered_a centered_b)
  let denom_a = f32.sqrt (f32.sum (map (\x -> x * x) centered_a))
  let denom_b = f32.sqrt (f32.sum (map (\x -> x * x) centered_b))
  in numerator / (denom_a * denom_b + 1e-8)

-- Batched pairwise distance matrix computation
-- Highly parallel: O(n^2 * d) but distributes across 8 GPUs
def pairwise_distances [n] [d] (vectors: [n][d]f32): [n][n]f32 =
  map (\vec_i ->
    map (\vec_j -> euclidean_distance vec_i vec_j) vectors
  ) vectors

-- K-means clustering for IVF index building
-- Lloyd's algorithm parallelized
def kmeans [n] [d] (k: i64) (max_iters: i64) 
                   (data: [n][d]f32): [k][d]f32 =
  -- Initialize centroids: random sample from data
  let initial_centroids = take k data

  -- Iterate
  let (final_centroids, _) = 
    loop (centroids, iter) = (initial_centroids, 0) 
    while iter < max_iters do
      -- Assignment step
      let assignments = assign_to_clusters data centroids

      -- Update step: recompute centroids
      let new_centroids = 
        map (\cluster_idx ->
          let cluster_points = 
            filter (\(_, assignment) -> assignment == cluster_idx) 
                   (zip data assignments)
            |> map (.0)
          let cluster_size = length cluster_points
          let sum_vec = reduce_comm (map2 (+)) (replicate d 0.0) cluster_points
          in map (\x -> x / f32.i64 cluster_size) sum_vec
        ) (iota k)

      in (new_centroids, iter + 1)

  in final_centroids

-- Matrix-vector multiplication (for transformer attention)
def matvec [m] [n] (matrix: [m][n]f32) (vector: [n]f32): [m]f32 =
  map (\row -> f32.sum (map2 (*) row vector)) matrix

-- Batch matrix multiplication (BMM) for multi-head attention
def batch_matmul [b] [m] [n] [p] (A: [b][m][n]f32) (B: [b][n][p]f32): [b][m][p]f32 =
  map2 (\a_mat b_mat ->
    map (\a_row ->
      map (\b_col_idx ->
        let b_col = map (\b_row -> b_row[b_col_idx]) b_mat
        in f32.sum (map2 (*) a_row b_col)
      ) (iota p)
    ) a_mat
  ) A B

-- Softmax for attention weights
def softmax [n] (logits: [n]f32): [n]f32 =
  let max_logit = f32.maximum logits
  let exp_logits = map (\x -> f32.exp (x - max_logit)) logits
  let sum_exp = f32.sum exp_logits
  in map (\x -> x / sum_exp) exp_logits

-- Multi-head attention kernel (simplified)
def multi_head_attention [b] [seq] [d] [h] 
                          (queries: [b][seq][d]f32)
                          (keys: [b][seq][d]f32)
                          (values: [b][seq][d]f32)
                          (head_dim: i64): [b][seq][d]f32 =
  let dk = f32.i64 head_dim
  let scale = 1.0 / f32.sqrt dk

  -- Compute attention scores
  let scores = batch_matmul queries keys
  let scaled_scores = map (map (map (\x -> x * scale))) scores

  -- Apply softmax
  let attn_weights = map (map softmax) scaled_scores

  -- Apply to values
  let output = batch_matmul attn_weights values

  in output
