// C wrapper for calling Futhark GPU kernels from other languages

#include "vector_search.h"
#include <stdio.h>
#include <stdlib.h>
#include <cuda_runtime.h>

typedef struct {
    struct futhark_context *ctx;
    struct futhark_f32_2d *database;
    int64_t num_vectors;
    int64_t embedding_dim;
} FaissFutharkIndex;

FaissFutharkIndex* faiss_futhark_create_index(float *embeddings, 
                                               int64_t n, 
                                               int64_t d) {
    FaissFutharkIndex *index = malloc(sizeof(FaissFutharkIndex));

    struct futhark_context_config *cfg = futhark_context_config_new();
    futhark_context_config_set_device(cfg, 0); // First B200 GPU

    index->ctx = futhark_context_new(cfg);
    index->num_vectors = n;
    index->embedding_dim = d;

    // Transfer embeddings to GPU
    index->database = futhark_new_f32_2d(index->ctx, embeddings, n, d);

    // Normalize embeddings on GPU
    struct futhark_f32_2d *normalized = NULL;
    int err = futhark_entry_normalize_embeddings(
        index->ctx,
        &normalized,
        index->database
    );

    if (err != 0) {
        fprintf(stderr, "Futhark error: %s\n", futhark_context_get_error(index->ctx));
        return NULL;
    }

    // Replace with normalized
    futhark_free_f32_2d(index->ctx, index->database);
    index->database = normalized;

    futhark_context_config_free(cfg);

    return index;
}

int faiss_futhark_search(FaissFutharkIndex *index,
                         float *queries,
                         int64_t nq,
                         int64_t k,
                         int64_t *out_indices,
                         float *out_scores) {
    // Create query array on GPU
    struct futhark_f32_2d *query_array = futhark_new_f32_2d(
        index->ctx,
        queries,
        nq,
        index->embedding_dim
    );

    // Call Futhark kernel
    struct futhark_i64_2d *indices = NULL;
    struct futhark_f32_2d *scores = NULL;

    int err = futhark_entry_search_vectors(
        index->ctx,
        &indices,
        &scores,
        k,
        query_array,
        index->database
    );

    if (err != 0) {
        fprintf(stderr, "Search error: %s\n", futhark_context_get_error(index->ctx));
        return -1;
    }

    // Copy results back to host
    futhark_values_i64_2d(index->ctx, indices, out_indices);
    futhark_values_f32_2d(index->ctx, scores, out_scores);

    // Cleanup
    futhark_free_f32_2d(index->ctx, query_array);
    futhark_free_i64_2d(index->ctx, indices);
    futhark_free_f32_2d(index->ctx, scores);

    return 0;
}

void faiss_futhark_free_index(FaissFutharkIndex *index) {
    futhark_free_f32_2d(index->ctx, index->database);
    futhark_context_free(index->ctx);
    free(index);
}

// Multi-GPU variant using all 8 B200 GPUs
typedef struct {
    FaissFutharkIndex *shards[8];
    int64_t vectors_per_shard;
} FaissFutharkMultiGPUIndex;

FaissFutharkMultiGPUIndex* faiss_futhark_create_multi_gpu_index(
    float *embeddings,
    int64_t n,
    int64_t d
) {
    FaissFutharkMultiGPUIndex *index = malloc(sizeof(FaissFutharkMultiGPUIndex));
    index->vectors_per_shard = (n + 7) / 8; // Divide among 8 GPUs

    // Create shard on each GPU
    for (int gpu_id = 0; gpu_id < 8; gpu_id++) {
        int64_t start_idx = gpu_id * index->vectors_per_shard;
        int64_t end_idx = start_idx + index->vectors_per_shard;
        if (end_idx > n) end_idx = n;
        int64_t shard_size = end_idx - start_idx;

        // Get shard data
        float *shard_data = embeddings + (start_idx * d);

        // Create index on specific GPU
        cudaSetDevice(gpu_id);
        index->shards[gpu_id] = faiss_futhark_create_index(shard_data, shard_size, d);
    }

    return index;
}

int faiss_futhark_search_multi_gpu(FaissFutharkMultiGPUIndex *index,
                                   float *queries,
                                   int64_t nq,
                                   int64_t k,
                                   int64_t *out_indices,
                                   float *out_scores) {
    // Search all shards in parallel (one thread per GPU)
    #pragma omp parallel for num_threads(8)
    for (int gpu_id = 0; gpu_id < 8; gpu_id++) {
        int64_t *shard_indices = malloc(nq * k * sizeof(int64_t));
        float *shard_scores = malloc(nq * k * sizeof(float));

        cudaSetDevice(gpu_id);
        faiss_futhark_search(index->shards[gpu_id], queries, nq, k, 
                            shard_indices, shard_scores);

        // Merge results (synchronized after parallel loop)
        // ... merging logic ...

        free(shard_indices);
        free(shard_scores);
    }

    return 0;
}
