# PageRank algorithm in Bend (Python-like syntax)
# Runs on HVM2 with automatic parallelization across GPU cores

type Graph:
  nodes: List[Int]
  edges: List[Tuple[Int, Int]]  # (from, to)
  out_degrees: Map[Int, Int]

def build_graph(edges):
  """Construct graph from edge list"""
  nodes = set()
  out_degrees = {}

  for (src, dst) in edges:
    nodes.add(src)
    nodes.add(dst)
    out_degrees[src] = out_degrees.get(src, 0) + 1

  return Graph(
    nodes=list(nodes),
    edges=edges,
    out_degrees=out_degrees
  )

def initialize_ranks(nodes):
  """Initialize PageRank scores uniformly"""
  n = len(nodes)
  initial_rank = 1.0 / n
  return {node: initial_rank for node in nodes}

def pagerank_iteration(graph, ranks, damping=0.85):
  """Single PageRank iteration - fully parallelizable"""
  n = len(graph.nodes)
  teleport = (1.0 - damping) / n

  # Parallel map over all nodes
  def compute_new_rank(node):
    # Find incoming edges
    incoming_contrib = fold 0.0 for (src, dst) in graph.edges:
      if dst == node:
        contrib = ranks[src] / graph.out_degrees[src]
        bend contrib
      else:
        bend 0.0

    new_rank = teleport + damping * incoming_contrib
    return (node, new_rank)

  # HVM2 automatically parallelizes this map across GPU cores
  new_ranks_list = [compute_new_rank(node) for node in graph.nodes]

  return dict(new_ranks_list)

def pagerank(graph, iterations=50, damping=0.85):
  """Full PageRank algorithm"""
  ranks = initialize_ranks(graph.nodes)

  # Iterate (each iteration is GPU-parallelized)
  for i in range(iterations):
    ranks = pagerank_iteration(graph, ranks, damping)

  return ranks

def top_k_nodes(ranks, k):
  """Return top K nodes by PageRank score"""
  sorted_ranks = sorted(ranks.items(), key=lambda x: x[1], reverse=True)
  return sorted_ranks[:k]

# Entry point for external calls
def main(edges_data, num_iterations=50):
  """
  edges_data: List of (source_id, target_id) tuples
  Returns: List of (node_id, pagerank_score) sorted by score
  """
  graph = build_graph(edges_data)
  ranks = pagerank(graph, iterations=num_iterations)
  return sorted(ranks.items(), key=lambda x: x[1], reverse=True)
