# Link graph analysis for web search engine
# Implements HITS algorithm and community detection

type LinkGraph:
  nodes: Set[Int]
  forward_links: Map[Int, Set[Int]]   # node -> outgoing links
  backward_links: Map[Int, Set[Int]]  # node -> incoming links

def build_link_graph(documents):
  """
  documents: List of (doc_id, outgoing_urls)
  Returns: LinkGraph structure
  """
  forward_links = {}
  backward_links = {}
  nodes = set()

  for (doc_id, urls) in documents:
    nodes.add(doc_id)
    forward_links[doc_id] = set(urls)

    for target in urls:
      nodes.add(target)
      if target not in backward_links:
        backward_links[target] = set()
      backward_links[target].add(doc_id)

  return LinkGraph(
    nodes=nodes,
    forward_links=forward_links,
    backward_links=backward_links
  )

def hits_iteration(graph, auth_scores, hub_scores):
  """
  HITS (Hyperlink-Induced Topic Search) algorithm iteration
  Authority update: sum of hub scores of incoming links
  Hub update: sum of authority scores of outgoing links
  """

  # Authority update (parallel over all nodes)
  def update_authority(node):
    incoming = graph.backward_links.get(node, set())
    auth = fold 0.0 for in_node in incoming:
      bend hub_scores[in_node]
    return (node, auth)

  new_auth = dict([update_authority(n) for n in graph.nodes])

  # Normalize
  auth_norm = sqrt(fold 0.0 for score in new_auth.values(): bend score * score)
  new_auth = {n: s / auth_norm for (n, s) in new_auth.items()}

  # Hub update (parallel over all nodes)
  def update_hub(node):
    outgoing = graph.forward_links.get(node, set())
    hub = fold 0.0 for out_node in outgoing:
      bend new_auth[out_node]
    return (node, hub)

  new_hub = dict([update_hub(n) for n in graph.nodes])

  # Normalize
  hub_norm = sqrt(fold 0.0 for score in new_hub.values(): bend score * score)
  new_hub = {n: s / hub_norm for (n, s) in new_hub.items()}

  return (new_auth, new_hub)

def hits_algorithm(graph, iterations=50):
  """Full HITS algorithm"""
  # Initialize scores
  n = len(graph.nodes)
  init_score = 1.0 / sqrt(n)
  auth_scores = {node: init_score for node in graph.nodes}
  hub_scores = {node: init_score for node in graph.nodes}

  # Iterate
  for i in range(iterations):
    (auth_scores, hub_scores) = hits_iteration(graph, auth_scores, hub_scores)

  return (auth_scores, hub_scores)

def detect_communities_louvain(graph, resolution=1.0):
  """
  Louvain community
